def numeric_summary(values):
    nums = [v for v in values if isinstance(v, (int, float)) and not isinstance(v, bool)]
    if not nums:
        return {"count": 0, "min": None, "max": None, "mean": None}
    return {"count": len(nums), "min": min(nums), "max": max(nums), "mean": round(sum(nums)/len(nums), 2)}

def word_frequencies(words):
    counts = {}
    for w in words:
        w = w.strip().lower()
        if not w:
            continue
        counts[w] = counts.get(w, 0) + 1
    return counts

def impute_median(values):
    nums = sorted(v for v in values if isinstance(v, (int, float)) and not isinstance(v, bool))
    if not nums:
        return list(values)
    n = len(nums)
    if n % 2 == 1:
        med = nums[n // 2]
    else:
        med = round((nums[n // 2 - 1] + nums[n // 2]) / 2, 2)
    return [med if v is None else v for v in values]

def min_max_scale(values):
    mn, mx = min(values), max(values)
    if mx == mn:
        return [0.0 for _ in values]
    return [round((x - mn) / (mx - mn), 4) for x in values]
